import MtCard from "@/components/MtCard.vue";
import MtTextField from "@/components/MtTextField.vue";
import MtPasswordTextField from "@/components/MtPasswordTextField.vue";
export default {
  components: {
    MtCard,
    MtTextField,
    MtPasswordTextField
  },
  props: {
    //
  },
  data: () => ({
    height: 0,
    width: 0,
    cardWidth: 395,
    account: "",
    password: "",
    loading: false
  }),
  mounted: async function () {
    //
  },
  computed: {
    textFieldStyle: function () {
      const width = this.cardWidth + "px";
      return {
        width: width,
        "margin-bottom": "8px"
      };
    }
  },
  methods: {
    login: async function () {
      this.loading = true;
      let result = false;
      await this.$mtapi.auth.login(this.account, this.password).then(response => result = response.data).catch(err => alert("error " + JSON.stringify(err.response.data.message)));
      if (result) {
        alert("result");
        this.loading = false;
      } else {
        location.reload();
      }
    }
  }
};
